@Override
    public void close() throws IOException {
        if (closed) {
            return;
        }
        IOException ioException = null;
        if (closeables != null) {
            for (Closeable closeable : closeables) {
                if (closeable == null) {
                    continue;
                }
                try {
                    closeable.close();
                } catch (IOException ioE) {
                    if (ioException != null) {
                        ioException = ioE;
                    }
                }
            }
        }
        if (ioException != null) {
            throw ioException;
        }
        closed = true;
    }

